function F_stderr_parse_progress(arg0) {
	const { stderr_line } = arg0;
	let { full_duration, seek_size_bytes } = arg0;
	full_duration = parseFloat(`${full_duration}`);
	const progress = {};
	const fps = stderr_line.match(/fps=\s*(\d+)/);
	const size = stderr_line.match(/size=\s*([\d.]+)([kMGT]?B)/);
	const time = stderr_line.match(/time=(\d{2}:\d{2}:\d{2}\.\d{2})/);
	const speed = stderr_line.match(/speed=\s*([\d.]+x)/);
	const bitrate = stderr_line.match(/bitrate=\s*([\d.]+kbits\/s)/);
	if (fps?.[1]) progress.fps = parseInt(fps[1]);
	if (size?.[1]) {
		const value = parseFloat(size[1]);
		const unit = size[2] || "B";
		const seek_size_bytes = Math.round(value * ({
			B: 1,
			kB: 1024,
			MB: 1024 ** 2,
			GB: 1024 ** 3,
			TB: 1024 ** 4
		}[unit] || 1));
		progress.size_bytes = seek_size_bytes;
		progress.size = NS_ff.F_format_size(seek_size_bytes);
	}
	if (time) progress.seek_time = time[1];
	if (speed) progress.speed = speed[1];
	if (bitrate) progress.bitrate = bitrate[1];
	if (time && full_duration && full_duration > 0) {
		progress.duration_hms = secondsToHMS(full_duration);
		progress.duration_seconds = full_duration;
		if (time?.[1]) {
			const currentSeconds = timeToSecondsPrecise(time[1]);
			progress.percent = Math.min(100, Math.max(0, currentSeconds / full_duration * 100));
			progress.remaining_seconds = Math.max(0, full_duration - currentSeconds);
			progress.remaining_hms = secondsToHMS(progress.remaining_seconds);
		}
	}
	return progress;
}
function secondsToHMS(totalSeconds) {
	const hours = Math.floor(totalSeconds / 3600);
	const minutes = Math.floor(totalSeconds % 3600 / 60);
	const seconds = Math.floor(totalSeconds % 60);
	return [
		hours.toString().padStart(2, "0"),
		minutes.toString().padStart(2, "0"),
		seconds.toString().padStart(2, "0")
	].join(":");
}
function timeToSecondsPrecise(timeStr) {
	const hms = timeStr.split(":");
	const h = hms[0];
	const m = hms[1];
	const sms = hms[2].split(".");
	const s = sms[0];
	const ms = sms[1];
	return parseInt(h) * 3600 + parseInt(m) * 60 + parseInt(s) + (parseInt(ms) || 0) / 100;
}
